1	import Link from "next/link";
2	import { db } from "@/lib/db";
3	import { impersonating, requireUser } from "@/lib/auth";
4	import { Badge, fmtMoney, fmtBytes, timeAgo } from "@/components/ui/primitives";
5	import { PortalHero } from "@/components/portal/PortalHero";
6	import { MeterBar } from "@/components/ui/charts";
7	import { AddFunds } from "@/components/customer/AddFunds";
8	import { SandboxTopUp } from "@/components/customer/SandboxTopUp";
9	import { SANDBOX } from "@/lib/sandbox";
10	import { formatInvoiceNumber, invoiceBranding } from "@/lib/invoices";
11	import {
12	  BW_PERIOD_DAYS,
13	  bwUsageView,
14	  fmtBwDate,
15	  fmtBwSpan,
16	  readBwMeterHealth,
17	} from "@/lib/bandwidth";
18	import { CouponField } from "@/components/customer/CouponField";
19	import { RedeemGift } from "@/components/customer/RedeemGift";
20	// AutoRecharge used to be commented out here because nothing could charge the saved
21	// threshold — no customer could put a card on file at all. That gap is now closed by
22	// the payment-method card below, and `autoRechargeSweep` in worker/billing.ts really
23	// does charge the saved card, so the feature is rendered — but only to accounts that
24	// actually have a card, because without one it still does nothing.
25	import { AutoRecharge } from "@/components/customer/AutoRecharge";
26	import { BillingProfile } from "@/components/customer/BillingProfile";
27	import { SpendControls } from "@/components/customer/SpendControls";
28	import { monthSpendCents } from "@/lib/spend-caps";
29	import { stripeConfigured } from "@/lib/stripe";
30	import { InvoiceStatusBadge, DownloadInvoiceButton } from "@/components/customer/InvoiceViews";
31	import {
32	  AddCardButton,
33	  CardSetupReturn,
34	  RemoveCardButton,
35	  SettleNowButton,
36	} from "@/components/customer/PaymentMethod";
37	import {
38	  brandLabel,
39	  cardDisplayLabel,
40	  cardExpiresAt,
41	  hasChargeableCard,
42	  renewalCharge,
43	} from "@/lib/stripe-cards";
44	import {
45	  CARD_EXPIRY_WARN_DAYS,
46	  CARD_SUSPEND_DAY,
47	  DUNNING_RETRY_ATTEMPTS,
48	  LAST_RETRY_DAY,
49	  RETRY_DAYS,
50	  dunningView,
51	} from "@/lib/dunning-schedule";
52	import { walletSplit } from "@/lib/wallet-split";
53	import { dedicatedIpMonthlyCents } from "@/lib/dedicated-ip";
54	import { annualDiscountPct } from "@/lib/annual-discount";
55	import { DEFAULT_ANNUAL_DISCOUNT_PCT } from "@/lib/billing-terms";
56	import { extraDiskPerGbCents } from "@/lib/disk-expand";
57	import { backupPlusMonthlyCents } from "@/lib/backup-upgrade";
58	import { getSettingBool, getSettingInt } from "@/lib/settings";
59	import { taxContextForUser } from "@/lib/tax";
60	
61	export const dynamic = "force-dynamic";
62	
63	export default async function BillingPage({
64	  searchParams,
65	}: {
66	  searchParams: Promise<{ paid?: string; canceled?: string; card_setup?: string }>;
67	}) {
68	  const { paid, canceled, card_setup: cardSetup } = await searchParams;
69	  const user = await requireUser();
70	  // Resolved once for the whole page so every row formats identically.
71	  const invoiceNumberPrefix = (await invoiceBranding()).numberPrefix;
72	  const [transactions, paidServers, bwServers, invoices] = await Promise.all([
73	    db.walletTransaction.findMany({
74	      where: { userId: user.id },
75	      orderBy: { createdAt: "desc" },
76	      take: 60,
77	    }),
78	    db.server.findMany({
79	      where: { userId: user.id, isFree: false, status: { not: "DELETING" } },
80	      // `gamePlan` and `dedicatedIp` are what `renewalCharge` needs to price a
81	      // renewal correctly. Without them this page could only reach for
82	      // `plan.priceCents`, which is a different number — see the renewals block
83	      // below for the incident.
84	      include: { plan: true, gamePlan: true, dedicatedIp: true },
85	      orderBy: { expiresAt: "asc" },
86	    }),
87	    db.server.findMany({
88	      where: { userId: user.id, status: { not: "DELETING" } },
89	      include: { plan: true },
90	      orderBy: { createdAt: "asc" },
91	    }),
92	    db.invoice.findMany({
93	      where: { userId: user.id },
94	      orderBy: { createdAt: "desc" },
95	      take: 5,
96	    }),
97	  ]);
98	
99	  /* ---------------- Card on file + anything overdue ---------------- */
100	
101	  // An admin impersonating a customer must not be able to attach, remove or use a
102	  // card on their account — `assertNotImpersonating` refuses these actions server
103	  // side, so the controls are hidden rather than left to throw when clicked.
104	  const isImpersonating = (await impersonating()) !== null;
105	  const cardOnFile = hasChargeableCard(user);
106	  const cardLabel = cardDisplayLabel({
107	    brand: user.cardBrand,
108	    last4: user.cardLast4,
109	    expMonth: user.cardExpMonth,
110	    expYear: user.cardExpYear,
111	  });
112	
113	  // The saved card's own health. `cardExpiresAt` returns the first instant the card
114	  // is no longer valid — a card works THROUGH the last day of its expiry month.
115	  const now = new Date();
116	  const cardExpiry =
117	    user.cardExpMonth && user.cardExpYear
118	      ? cardExpiresAt(user.cardExpMonth, user.cardExpYear)
119	      : null;
120	  const cardExpired = cardExpiry !== null && cardExpiry <= now;
121	  const cardExpiringSoon =
122	    cardExpiry !== null &&
123	    !cardExpired &&
124	    cardExpiry.getTime() - now.getTime() <= CARD_EXPIRY_WARN_DAYS * 86_400_000;
125	
126	  // Servers the renewal sweep is actively collecting for. The status filter is the
127	  // same one `dueServers` in worker/billing.ts uses, so this panel can never claim
128	  // a retry is coming for a server the sweep does not look at. SUSPENDED servers
129	  // are handled separately below — the sweep skips those entirely.
130	  const overdueServers = await db.server.findMany({
131	    where: {
132	      userId: user.id,
133	      isFree: false,
134	      expiresAt: { lt: now },
135	      status: { in: ["RUNNING", "STOPPED"] },
136	    },
137	    include: { plan: true, gamePlan: true, dedicatedIp: true },
138	    orderBy: { expiresAt: "asc" },
139	  });
140	  const suspendedUnpaid = await db.server.findMany({
141	    where: { userId: user.id, status: "SUSPENDED", suspendReason: "UNPAID" },
142	    orderBy: { expiresAt: "asc" },
143	  });
144	
145	  // Prices and dunning windows are read exactly as the worker reads them, so the
146	  // amount quoted here is the amount the sweep will actually try to take.
147	  const graceDays = Math.max(
148	    0,
149	    await getSettingInt("dunning_grace_days", Number(process.env.NXEON_GRACE_DAYS ?? 3)),
150	  );
151	  const autoSuspend = await getSettingBool("auto_suspend_enabled", true);
152	  // VAT/GST for this customer (Finding 1) so every renewal figure on this page is
153	  // tax-inclusive and equals what the sweep / Renew now / settle-outstanding charge.
154	  const taxRatePercent = (await taxContextForUser(user)).ratePercent;
155	  const prices =
156	    paidServers.length > 0
157	      ? {
158	          ipMonthlyCents: await dedicatedIpMonthlyCents(),
159	          extraDiskPerGbCents: await extraDiskPerGbCents(),
160	          backupPlusCents: await backupPlusMonthlyCents(),
161	          annualDiscountPct: await annualDiscountPct(),
162	          taxRatePercent,
163	        }
164	      // No paid servers -> renewalCharge is never called; the shipped default just
165	      // satisfies the required field.
166	      : { ipMonthlyCents: 0, extraDiskPerGbCents: 0, backupPlusCents: 0, annualDiscountPct: DEFAULT_ANNUAL_DISCOUNT_PCT, taxRatePercent };
167	
168	  // EVERY recurring figure on this page is priced through `renewalCharge` — the
169	  // one function worker/billing.ts sweeps with, the saved-card path charges
170	  // through, and the "Renew now" button quotes from (lib/renewal-quote.ts).
171	  //
172	  // "Upcoming renewals" used to print `plan.priceCents` beside a renewal DATE.
173	  // That is not the amount that comes out on that date: on an annual Starter it
174	  // read $8.99 next to the day the sweep takes $97.09, and on a game server it
175	  // read the base VPS plan's $8.99 for a product sold at $4.99. It is the same
176	  // defect as the "Renew now (+30 days, $8.99)" button that took $97.09 — a
177	  // SECOND price formula, not a wrong one. There is one, and it lives in
178	  // lib/renewal-charge.ts.
179	  const renewals = paidServers.map((s) => ({ server: s, charge: renewalCharge(s, prices) }));
180	  // Monthly run-rate. Deliberately a division of the AUTHORITATIVE term total
181	  // rather than a fresh sum of `plan.priceCents`: an annual server's monthly
182	  // share is its real term price spread over the months it buys, and a game
183	  // server contributes its game-plan price, not the VPS plan it is built on.
184	  const monthlySpendCents = renewals.reduce(
185	    (sum, r) => sum + Math.round(r.charge.totalCents / Math.max(1, r.charge.months)),
186	    0,
187	  );
188	  const upcoming = renewals.filter((r) => r.server.expiresAt !== null);
189	
190	  // One quote per overdue server, built from the SAME `renewalCharge` + `walletSplit`
191	  // pair that `settleOutstanding` and the sweep use. The three must never disagree:
192	  // a page that quotes a different total than the charge that follows is the exact
193	  // failure both of those call sites carry a comment about.
194	  const overdue = overdueServers.map((s) => {
195	    const charge = renewalCharge(s, prices);
196	    const split = walletSplit({
197	      dueCents: charge.totalCents,
198	      balanceCents: user.balanceCents,
199	      useWallet: true,
200	    });
201	    return {
202	      server: s,
203	      charge,
204	      split,
205	      view: dunningView(s, { hasCard: cardOnFile, graceDays, autoSuspend, now }),
206	    };
207	  });
208	  const totalOutstandingCents = overdue.reduce((sum, o) => sum + o.charge.totalCents, 0);
209	  // A server can be past its expiry date and still fully funded — the sweep runs every
210	  // ten minutes, so "overdue" and "short of money" are different things. Only the
211	  // second one is an emergency, and only it gets the red treatment.
212	  const anyShortfall = overdue.some((o) => o.split.cardCents > 0);
213	  // "The card failed" is not a column — `dunningStage` counts card attempts that
214	  // have FAILED for the current unpaid period, so a stage above zero while a card is
215	  // on file IS the saved card having been declined. Anything less specific here
216	  // would be guessing.
217	  const cardDeclined = cardOnFile && overdue.some((o) => o.view.inDunning);
218	  const fmtDay = (d: Date) =>
219	    d.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
220	  // Widened from its literal type on purpose: the copy below pluralises off this
221	  // number, and TypeScript rejects `=== 1` as impossible against the literal `3` —
222	  // which would leave the sentence unable to survive a change to the ladder.
223	  const retryAttempts: number = DUNNING_RETRY_ATTEMPTS;
224	  // "1, 3 and 5" — built from the real ladder rather than written out, so a change to
225	  // DUNNING_RETRY_ATTEMPTS reads correctly here instead of silently going stale.
226	  const retryDayList =
227	    RETRY_DAYS.length === 1
228	      ? String(RETRY_DAYS[0])
229	      : `${RETRY_DAYS.slice(0, -1).join(", ")} and ${RETRY_DAYS[RETRY_DAYS.length - 1]}`;
230	
231	  // Bandwidth usage: metered transfer (bwIn + bwOut, written by the worker's
232	  // metering sweep) vs plan allowance (bandwidthTB * 1e12 bytes).
233	  //
234	  // This panel used to divide the raw columns by the allowance and print the
235	  // result. Nothing wrote those columns, so it read a permanent "0 B / 20 TB ·
236	  // 0%" under the title "Transfer used this cycle" — a figure that looked
237	  // authoritative and was pure fiction. Everything shown now goes through
238	  // bwUsageView, which reports the period the meter ACTUALLY covers and
239	  // withholds the percentage entirely until a sample exists.
240	  const bwHealth = await readBwMeterHealth();
241	  const bandwidth = bwServers.map((s) => ({
242	    server: s,
243	    view: bwUsageView(s, s.plan.bandwidthTB * 1e12, bwHealth),
244	  }));
245	  const bwMeasured = bwHealth.startedAt !== null;
246	  const totalUsedBytes = bandwidth.reduce((sum, b) => sum + b.view.usedBytes, 0);
247	  const totalAllowanceBytes = bandwidth.reduce((sum, b) => sum + b.view.allowanceBytes, 0);
248	  const totalPct = totalAllowanceBytes > 0 ? (totalUsedBytes / totalAllowanceBytes) * 100 : 0;
249	  const bwPartial = bandwidth.some((b) => b.view.partial);
250	  const bwGap = bandwidth.some((b) => b.view.hasGap);
251	  const meterColor = (pct: number) => (pct > 100 ? "#ef4444" : pct > 80 ? "#f59e0b" : "#6f47f5");
252	  const pctTone = (pct: number) =>
253	    pct > 100 ? "text-red-400" : pct > 80 ? "text-amber-400" : "text-slate-400";
254	
255	  return (
256	    <div className="space-y-6">
257	      <PortalHero variant="billing" title="Billing" sub="Wallet, renewals and transaction history." />
258	      <div className="-mt-3"><Link href="/dashboard/invoices" className="text-sm text-brand-300 hover:underline">View &amp; download invoices →</Link></div>
259	
260	      {paid === "1" && (
261	        <div className="card border-emerald-500/30 bg-emerald-500/[0.06] text-sm text-emerald-300">
262	          Payment received — your balance updates within seconds. Refresh if you don&apos;t see it
263	          yet.
264	        </div>
265	      )}
266	      {canceled === "1" && (
267	        <div className="card border-amber-500/30 bg-amber-500/[0.06] text-sm text-amber-300">
268	          Checkout canceled — no charge was made.
269	        </div>
270	      )}
271	
272	      {/* The return leg from Stripe's hosted setup page. Stripe attaches the card
273	          to the customer BEFORE redirecting here, so this has to run and has to
274	          report what happened — see CardSetupReturn. */}
275	      {cardSetup && <CardSetupReturn sessionId={cardSetup} />}
276	
277	      {/* Nothing else on this page matters while a server is overdue, so it goes
278	          first — above the wallet, above everything. */}
279	      {overdue.length > 0 && (
280	        <div
281	          className={`card ${
282	            anyShortfall ? "border-red-500/30 bg-red-500/[0.05]" : "border-amber-500/30 bg-amber-500/[0.05]"
283	          }`}
284	        >
285	          <div className="flex flex-wrap items-start justify-between gap-4">
286	            <div>
287	              <div className="flex items-center gap-2">
288	                <p className={`section-label ${anyShortfall ? "!text-red-300" : "!text-amber-300"}`}>
289	                  {anyShortfall ? "Action needed" : "Renewing shortly"}
290	                </p>
291	                <Badge tone={anyShortfall ? "red" : "amber"}>
292	                  {overdue.length} overdue renewal{overdue.length === 1 ? "" : "s"}
293	                </Badge>
294	              </div>
295	              <p className="mt-2 text-sm text-slate-300">
296	                {!anyShortfall
297	                  ? "Your wallet covers these — they complete automatically within a few minutes, with nothing for you to do."
298	                  : cardOnFile
299	                    ? cardDeclined
300	                      ? `We tried ${cardLabel ?? "your saved card"} and it was declined. Nothing is suspended yet.`
301	                      : `We'll charge ${cardLabel ?? "your saved card"} for anything your wallet doesn't cover.`
302	                    : "These can only be paid from your wallet balance, and it doesn't cover them."}
303	              </p>
304	            </div>
305	            <div className="text-right">
306	              <p className="text-xs text-slate-400">Total outstanding</p>
307	              <p className={`text-2xl font-bold ${anyShortfall ? "text-red-300" : "text-amber-300"}`}>
308	                {fmtMoney(totalOutstandingCents)}
309	              </p>
310	            </div>
311	          </div>
312	
313	          <ul className="mt-5 space-y-4">
314	            {overdue.map(({ server: s, charge, split, view }) => (
315	              <li
316	                key={s.id}
317	                className="rounded-lg border border-white/[0.08] bg-white/[0.02] p-4"
318	              >
319	                <div className="flex flex-wrap items-start justify-between gap-3">
320	                  <div className="min-w-0">
321	                    <Link
322	                      href={`/dashboard/servers/${s.id}`}
323	                      className="font-medium hover:text-brand-300"
324	                    >
325	                      {s.hostname}
326	                    </Link>
327	                    <p className="mt-0.5 text-xs text-slate-500">
328	                      {charge.label} · {fmtMoney(charge.totalCents)} for {charge.months} month
329	                      {charge.months === 1 ? "" : "s"} · expired {fmtDay(s.expiresAt!)}
330	                    </p>
331	                  </div>
332	                  <div className="shrink-0 text-right">
333	                    {/* `settleOutstanding` quotes the CARD leg, not the full total —
334	                        wallet credit is applied first — so the button is labelled
335	                        with the same number it will ask Stripe for. */}
336	                    {split.cardCents > 0 ? (
337	                      <>
338	                        <SettleNowButton serverId={s.id} />
339	                        <p className="mt-1 text-[11px] text-slate-500">
340	                          {fmtMoney(split.cardCents)} on your card
341	                          {split.walletApplied > 0
342	                            ? `, ${fmtMoney(split.walletApplied)} from your wallet`
343	                            : ""}
344	                        </p>
345	                      </>
346	                    ) : (
347	                      <p className="text-xs text-emerald-300">
348	                        Your wallet covers this — it renews automatically within a few minutes.
349	                      </p>
350	                    )}
351	                  </div>
352	                </div>
353	
354	                {/* Where they are in the ladder, and what happens next. */}
355	                <div className="mt-3 border-t border-white/[0.06] pt-3 text-xs">
356	                  {view.inDunning ? (
357	                    <p className="text-slate-400">
358	                      <span className="font-medium text-amber-300">
359	                        Attempt {view.attemptsMade} of {view.attemptsTotal} declined.
360	                      </span>{" "}
361	                      {view.exhausted
362	                        ? "That was the last automatic attempt."
363	                        : `We'll try again automatically ${
364	                            view.attemptsLeft === 1
365	                              ? "one more time"
366	                              : `${view.attemptsLeft} more times`
367	                          }${view.nextAttemptAt ? `, next on ${fmtDay(view.nextAttemptAt)}` : ""}.`}{" "}
368	                      {view.suspendAt ? (
369	                        <>
370	                          {s.hostname} keeps running until{" "}
371	                          <span className="font-medium text-slate-300">
372	                            {fmtDay(view.suspendAt)}
373	                          </span>
374	                          , when it pauses if the balance is still unpaid. Nothing is deleted then.
375	                        </>
376	                      ) : (
377	                        <>Automatic suspension is currently switched off on this account.</>
378	                      )}
379	                    </p>
380	                  ) : (
381	                    <p className="text-slate-400">
382	                      {cardOnFile ? (
383	                        <>
384	                          The next sweep will charge {cardLabel ?? "your saved card"} for the
385	                          shortfall.
386	                        </>
387	                      ) : (
388	                        <>No card on file, so nothing will be charged automatically.</>
389	                      )}{" "}
390	                      {view.suspendAt && (
391	                        <>
392	                          {s.hostname} pauses on{" "}
393	                          <span className="font-medium text-slate-300">
394	                            {fmtDay(view.suspendAt)}
395	                          </span>{" "}
396	                          if it is still unpaid.
397	                        </>
398	                      )}
399	                    </p>
400	                  )}
401	                </div>
402	              </li>
403	            ))}
404	          </ul>
405	
406	          {cardOnFile && (
407	            <p className="mt-4 text-xs text-slate-500">
408	              After a renewal fails we retry your card on day{RETRY_DAYS.length === 1 ? "" : "s"}{" "}
409	              {retryDayList} past expiry — {retryAttempts} attempt
410	              {retryAttempts === 1 ? "" : "s"}, each with an email — and only pause the
411	              server on day {CARD_SUSPEND_DAY}, a full day after the final notice.
412	            </p>
413	          )}
414	        </div>
415	      )}
416	
417	      {suspendedUnpaid.length > 0 && (
418	        <div className="card border-amber-500/30 bg-amber-500/[0.06]">
419	          <p className="section-label !text-amber-300">Paused for non-payment</p>
420	          <p className="mt-2 text-sm text-slate-300">
421	            {suspendedUnpaid.map((s) => s.hostname).join(", ")}{" "}
422	            {suspendedUnpaid.length === 1 ? "is" : "are"} paused, and the automatic renewal sweep no
423	            longer picks {suspendedUnpaid.length === 1 ? "it" : "them"} up. Top up your wallet and
424	            use <span className="font-medium text-slate-200">Renew now</span> on the server to bring{" "}
425	            {suspendedUnpaid.length === 1 ? "it" : "them"} back — your data is still there.
426	          </p>
427	          <div className="mt-3 flex flex-wrap gap-2">
428	            {suspendedUnpaid.map((s) => (
429	              <Link key={s.id} href={`/dashboard/servers/${s.id}`} className="btn-secondary py-1.5">
430	                {s.hostname}
431	              </Link>
432	            ))}
433	          </div>
434	        </div>
435	      )}
436	
437	      <div className="card relative overflow-hidden">
438	        <div
439	          className="pointer-events-none absolute inset-0"
440	          style={{
441	            background:
442	              "linear-gradient(120deg, rgb(59 130 246 / 0.12), rgb(111 71 245 / 0.14) 55%, transparent)",
443	          }}
444	        />
445	        <div className="relative flex flex-wrap items-end justify-between gap-6">
446	          <div>
447	            <p className="text-sm text-slate-400">Wallet balance</p>
448	            <p className="mt-1 text-4xl font-bold tracking-tight">
449	              <span className="grad-text">{fmtMoney(user.balanceCents)}</span>
450	            </p>
451	            <p className="mt-2 text-xs text-slate-500">
452	              Servers renew and domains register straight from this balance.
453	            </p>
454	          </div>
455	          <AddFunds />
456	        </div>
457	        {SANDBOX && (
458	          <div className="relative mt-5">
459	            <SandboxTopUp />
460	          </div>
461	        )}
462	        {/* Promo codes are only honored by the demo (non-Stripe) top-up path,
463	            which reads the coupon cookie in `topUp`. With Stripe configured,
464	            card checkout never redeems the code, so we hide the field to avoid
465	            promising a bonus that won't be credited. */}
466	        {!stripeConfigured() && (
467	          <div className="relative mt-5 border-t border-white/[0.06] pt-4">
468	            <CouponField />
469	          </div>
470	        )}
471	      </div>
472	
473	      {/* Card on file. This is the instrument worker/billing.ts auto-charges; the
474	          wallet above is what it funds. */}
475	      <div className="card">
476	        <div className="mb-3 flex flex-wrap items-center justify-between gap-3">
477	          <p className="section-label">Payment method</p>
478	          {cardOnFile && (
479	            <div className="flex flex-wrap items-center gap-2">
480	              {cardDeclined && <Badge tone="red">last charge declined</Badge>}
481	              {cardExpired && <Badge tone="red">expired</Badge>}
482	              {cardExpiringSoon && <Badge tone="amber">expires soon</Badge>}
483	              {!cardDeclined && !cardExpired && !cardExpiringSoon && (
484	                <Badge tone="green">active</Badge>
485	              )}
486	            </div>
487	          )}
488	        </div>
489	
490	        {!stripeConfigured() ? (
491	          <p className="text-sm text-slate-400">
492	            Card payments aren&apos;t configured on this installation, so there is nothing to save
493	            here yet. Renewals come out of your wallet balance — keep it topped up above.
494	          </p>
495	        ) : cardOnFile ? (
496	          <>
