11	async function ensureReferralCode(userId: string, current: string | null): Promise<string> {
12	  if (current) return current;
13	  for (let i = 0; i < 6; i++) {
14	    const code = generateReferralCode();
15	    const clash = await db.user.findUnique({ where: { referralCode: code } });
16	    if (clash) continue;
17	    try {
18	      await db.user.update({ where: { id: userId }, data: { referralCode: code } });
19	      return code;
20	    } catch {
21	      /* unique clash race — retry */
22	    }
23	  }
24	  const fallback = generateReferralCode(12);
25	  await db.user.update({ where: { id: userId }, data: { referralCode: fallback } });
26	  return fallback;
27	}
28	
29	export default async function ReferPage() {
30	  const user = await requireUser();
31	  const code = await ensureReferralCode(user.id, user.referralCode);
32	
33	  const [referredCount, rewardedCount] = await Promise.all([
34	    db.user.count({ where: { referredById: user.id } }),
35	    db.user.count({ where: { referredById: user.id, referralRewardedAt: { not: null } } }),
36	  ]);
37	
38	  const rewardCents = referralRewardCents();
39	  const appUrl = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/+$/, "");
40	  const link = `${appUrl}/register?ref=${code}`;
41	
42	  return (
43	    <div className="space-y-6">
44	      <PortalHero variant="refer" title="Refer & earn" sub="Invite friends and you both get wallet credit." />
45	      <div className="-mt-3"><Link href="/dashboard/affiliate" className="text-sm text-brand-300 hover:underline">Looking for the Affiliate program? →</Link></div>
46	
47	      <ReferralPanel
48	        link={link}
49	        code={code}
50	        rewardLabel={fmtMoney(rewardCents)}
51	        referredCount={referredCount}
52	        rewardedCount={rewardedCount}
53	      />
54	
55	      <div className="card">
56	        <p className="section-label mb-4">How it works</p>
57	        <ol className="space-y-3 text-sm text-slate-400">
58	          <li className="flex gap-3">
59	            <span className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full border border-brand-500/40 bg-brand-500/10 text-xs font-semibold text-brand-300">
60	              1
61	            </span>
62	            Share your personal referral link with friends and colleagues.
63	          </li>
64	          <li className="flex gap-3">
65	            <span className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full border border-brand-500/40 bg-brand-500/10 text-xs font-semibold text-brand-300">
66	              2
67	            </span>
